// Pull the anti-forgery token out of the tokenhtml fragment.
const html = String($input.first().json.data ?? $input.first().json.body ?? '');
const m = html.match(/name="__RequestVerificationToken"[^>]*value="([^"]+)"/i)
  || html.match(/value="([^"]+)"[^>]*name="__RequestVerificationToken"/i);
if (!m) throw new Error('Could not extract __RequestVerificationToken from tokenhtml');
return [{ json: { token: m[1] } }];

// Decode the grid records, keep towing-relevant categories, and only those newer
// than the per-workflow high-water mark (rvr_publishedlastupdatedate).
const staticData = $getWorkflowStaticData('global');
const highWater = staticData.roverHighWaterMark || '1970-01-01T00:00:00Z';

// Towing-relevant ADR categories; exclude T-series trailers (TA..TD) and others.
const KEEP = /^(M[ABCDE]?|N[ABC]\d?|MC|NA|NB1)$/i;

const payload = $input.first().json;
const records = Array.isArray(payload.Records) ? payload.Records : [];

function attr(rec, name) {
  const a = (rec.Attributes || []).find((x) => x.Name === name || x.AttributeName === name);
  return a ? (a.Value && a.Value.Value !== undefined ? a.Value.Value : a.Value) : null;
}

let maxSeen = highWater;
const out = [];
for (const rec of records) {
  const category = String(attr(rec, 'cv.rvr_categorytype') ?? attr(rec, 'rvr_categorytype') ?? '');
  const lastUpdated = String(attr(rec, 'rvr_publishedlastupdatedate') ?? '');
  const approvalId = attr(rec, 'rvr_approvalid') ?? rec.Id;
  const approvalNumber = attr(rec, 'rvr_approvalnumber');
  if (!approvalId) continue;
  if (!KEEP.test(category)) continue;
  if (lastUpdated && lastUpdated <= highWater) continue; // already imported
  if (lastUpdated > maxSeen) maxSeen = lastUpdated;
  out.push({ json: { approvalId, approvalNumber, category, lastUpdated } });
}

// Stash the candidate high-water mark; only commit it after a successful run.
staticData.roverPendingHighWaterMark = maxSeen;
staticData.roverFoundThisRun = out.length;
return out;

// Runs once all items are posted. Commit the high-water mark and raise a
// crawl-health flag if this run found 0 new records when it usually finds some
// (a 0-new run looks identical to 'no new approvals' — the scraper may be broken).
const staticData = $getWorkflowStaticData('global');
const found = staticData.roverFoundThisRun ?? 0;
const history = Array.isArray(staticData.roverRecentCounts) ? staticData.roverRecentCounts : [];
history.push(found);
while (history.length > 8) history.shift();
staticData.roverRecentCounts = history;

if (staticData.roverPendingHighWaterMark) {
  staticData.roverHighWaterMark = staticData.roverPendingHighWaterMark;
  delete staticData.roverPendingHighWaterMark;
}

const usuallyFinds = history.length >= 4 && history.slice(0, -1).some((n) => n > 0);
const alert = found === 0 && usuallyFinds;
return [{ json: { found, recentCounts: history, highWaterMark: staticData.roverHighWaterMark, crawlHealthAlert: alert } }];
